// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    function testFuzz_property(
        address from,
        address[] memory tos,
        uint256 v
    ) public {
        // Keep the domain admissible and wide: non-empty recipient list.
        uint256 n = tos.length;
        vm.assume(n > 0);
        vm.assume(n <= 100);
        // avoid address(0) to keep calls well-formed
        for (uint256 i = 0; i < n; ++i) {
            vm.assume(tos[i] != address(0));
        }

        Recorder rec = new Recorder();
        vm.prank(from);
        bool ok = false;
        try c.transfer(from, address(rec), tos, v) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // The reference succeeds and forwards exactly n well-formed transferFrom calls.
        assertTrue(ok && rec.count() == n);
    }
}

contract Recorder {
    uint256 public count;
    function transferFrom(address, address, uint256) external returns (bool) {
        count += 1;
        return true;
    }
}
